require_once __DIR__.'/../includes/bootstrap.php';$user=require_login();$st=$GLOBALS['pdo']->prepare('SELECT w.*,m.member_role,(SELECT COUNT(*) FROM datasets d WHERE d.workspace_id=w.id) dataset_count FROM workspaces w JOIN workspace_members m ON m.workspace_id=w.id WHERE m.user_id=? ORDER BY w.updated_at DESC');$st->execute([$user['id']]);$rows=$st->fetchAll();$current=current_workspace();require_once __DIR__.'/../includes/header.php';$layout='app';datanix_header('Workspaces','settings',$layout);
?>
<div class="page-head"><div><div class="section-kicker">ORGANIZATION</div><h1>Workspaces</h1><p>Setiap workspace memisahkan anggota, data, query, dashboard dan insight.</p></div><div class="page-head-actions"><a class="btn btn-primary" href="<?=e(url('workspaces/create.php'))?>">+ Workspace baru</a></div></div><div class="row g-3"><?php foreach($rows as $ws):?><div class="col-md-6 col-xl-4"><article class="panel stat-card" style="min-height:165px"><div class="d-flex justify-content-between"><div><span class="section-kicker"><?=e(strtoupper($ws['member_role']))?></span><h2 style="font-size:17px;margin:9px 0 5px"><?=e($ws['name'])?></h2></div><span class="badge-plan"><?=e(strtoupper($ws['plan']))?></span></div><p class="small-muted"><?=e(format_number((int)$ws['dataset_count']))?> dataset · Dibuat <?=e(date('d M Y',strtotime($ws['created_at'])))?></p><?php if((int)$ws['id']===(int)($current['id']??0)):?><span class="badge-soft green">Workspace aktif</span><?php else:?><form method="post" action="<?=e(url('workspaces/switch.php'))?>"><?=csrf_field()?><input type="hidden" name="workspace_id" value="<?=e($ws['id'])?>"><button class="btn btn-light-outline btn-sm">Buka workspace →</button></form><?php endif;?></article></div><?php endforeach;?><?php if(!$rows):?><div class="col-12"><div class="empty-state"><div class="empty-icon">▦</div><strong>Belum ada workspace</strong><p>Buat workspace untuk mulai mengatur dataset, pertanyaan dan dashboard.</p><a class="btn btn-primary" href="<?=e(url('workspaces/create.php'))?>">Buat workspace</a></div></div><?php endif;?></div>
